def render(node, ind: int = 0) -> str:
    if isinstance(node, str):
        return node

    if isinstance(node, Seq):
        if not node.items:
            return ""
        pad = "  " * ind
        return ("\n" + pad).join(render(it, ind) for it in node.items)

